# A WebAuthn credential that signs its owner in (generated by maquina:passkeys).
#
# Only the public key is stored; the private key never leaves the device or
# the password manager, so a leaked table cannot be used to sign in.
class Passkey < ApplicationRecord
  # AAGUIDs of common passkey providers, to give a new passkey a useful
  # default name. Providers that send no AAGUID fall back to "Passkey".
  PROVIDERS = {
    "fbfc3007-154e-4ecc-8c0b-6e020557d7bd" => "iCloud Keychain",
    "ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4" => "Google Password Manager",
    "adce0002-35bc-c60a-648b-0b25f1f05503" => "Chrome on Mac",
    "08987058-cadc-4b81-b6e1-30de50dcbe96" => "Windows Hello",
    "bada5566-a7aa-401f-bd96-45619a55120d" => "1Password",
    "d548826e-79b4-db40-a3d8-11116f7e8349" => "Bitwarden"
  }.freeze

  belongs_to :user

  validates :credential_id, presence: true, uniqueness: true
  validates :public_key, presence: true
  validates :name, presence: true, length: {maximum: 100}

  def self.default_name(aaguid)
    PROVIDERS.fetch(aaguid, "Passkey")
  end

  def record_use!(sign_count)
    update!(sign_count: sign_count, last_used_at: Time.current)
  end

  # Synced through a provider (iCloud Keychain, Google Password Manager, a
  # password manager) rather than bound to one device.
  def synced?
    backed_up?
  end
end
